def max_sum(tri, n):
    """Write a function to find the maximum sum in the given right triangle of numbers."""
    if not tri or n <= 0:
        return 0

    rows = tri[:n]
    dp = list(rows[-1])
    for i in range(len(rows) - 2, -1, -1):
        row = rows[i]
        updated = []
        for j, value in enumerate(row):
            successors = dp[j:j + 2]
            if successors:
                updated.append(value + max(successors))
            else:
                updated.append(value)
        dp = updated
    return dp[0] if dp else 0
